 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 0}, key=lambda c: min((r, col) for r, row in enumerate(grid) for col, v in enumerate(row) if v == c)[1])
    objects = []
    for color in colors:
        cells = [(r, col) for r, row in enumerate(grid) for col, v in enumerate(row) if v == color]
        r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
        c0, c1 = min(col for _, col in cells), max(col for _, col in cells)
        shape = [[grid[r][col] for col in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
        objects.append(shape)

    out = [[0] * w for _ in range(h)]
    r0 = c0 = 0
    for shape in objects:
        for r, row in enumerate(shape):
            for col, value in enumerate(row):
                if value:
                    rr, cc = r0 + r, c0 + col
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
        r0 += len(shape) - 1
        c0 += len(shape[0]) - 1
    return out
